# owner: platform
"""Lay students out in rows of seats, ordered by last name."""

from typing import List

from rosterkit.models import Student


def _check_inputs(students: List[Student], seats_per_row: int) -> None:
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, names: List[str]) -> str:
    return f"Row {number}: " + " | ".join(names)


# ---
def seat_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, such as `Row 1: Dunmere, Piet | Halloway, Juno`."""
    _check_inputs(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    starts = range(0, len(names), seats_per_row)
    chunks = [names[start:start + seats_per_row] for start in starts]
    return [_row_line(index, chunk) for index, chunk in enumerate(chunks, 1)]

after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _student(last: str, first: str) -> Student:
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Adler", "Rosa"),
        ]

    def test_sorts_by_last_name_and_fills_rows(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(
            lines,
            ["Row 1: Adler, Rosa | Dunmere, Piet", "Row 2: Halloway, Juno"],
        )

    def test_ties_break_on_first_name(self):
        pair = [_student("Lund", "Zed"), _student("Lund", "Abe")]
        self.assertEqual(seat_rows(pair, 2), ["Row 1: Lund, Abe | Lund, Zed"])

    def test_one_seat_per_row(self):
        self.assertEqual(len(seat_rows(self.students, 1)), 3)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -2)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
